package dev.zyon.platform.event; import net.minecraft.entity.player.EntityPlayer; public class RenderPlayerEvent extends Event{public final EntityPlayer entityPlayer;public final double x,y,z;public final float partialRenderTick;public RenderPlayerEvent(EntityPlayer p,double X,double Y,double Z,float partial){entityPlayer=p;x=X;y=Y;z=Z;partialRenderTick=partial;}public static final class Post extends RenderPlayerEvent {public Post(EntityPlayer p,double x,double y,double z,float partial){super(p,x,y,z,partial);}}}